  `customerId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `planNo` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `financedAmount` decimal(14,2) NOT NULL,
