  KEY `idx_we_sub` (`subscriptionId`,`status`),
  KEY `idx_we_retry` (`status`,`nextRetryAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
